#ifndef CAR_CONFIG_H
#define CAR_CONFIG_H

#include <stdint.h>

/* TIM1 period generated by CubeMX: 72 MHz / (3599 + 1) = 20 kHz. */
#define CAR_PWM_PERIOD             3599U
#define CAR_MOTOR_COMMAND_MAX     100

/* Set to -1 after wiring validation if a motor spins opposite to its peer. */
#define CAR_MOTOR_SIGN_FL          1
#define CAR_MOTOR_SIGN_FR          1
#define CAR_MOTOR_SIGN_RL          1
#define CAR_MOTOR_SIGN_RR          1

/* 编码器方向极性：台架上让轮子正转时，脉冲增量为正 */
#define CAR_ENCODER_SIGN_LEFT      1
#define CAR_ENCODER_SIGN_RIGHT     1

/* ------------------------------------------------------------------
 * 编码器与机械参数
 * ------------------------------------------------------------------
 * MG310：13 线霍尔编码器，TIM 编码器模式 TI12 为 4 倍频
 *   电机轴一圈 = 13 x 4 = 52 counts
 *   输出轴一圈 = 52 x 减速比
 *
 * 注意：减速比与轮径只影响 mm/s 和里程；counts/s（脉冲速度）不受影响。
 *       闭环先用脉冲速度，可以完全不依赖这两个待确认的常数。
 * ------------------------------------------------------------------ */
#define CAR_ENCODER_PPR            13U     /* 编码器线数（每转脉冲数） */
#define CAR_ENCODER_MULTIPLIER     4U      /* TI12 模式 = 4 倍频 */
#define CAR_ENCODER_CNT_PER_MOTOR_REV \
    (CAR_ENCODER_PPR * CAR_ENCODER_MULTIPLIER)              /* 52 */

#define CAR_GEAR_RATIO             30U     /* 减速比：待按实际型号确认 */
#define CAR_ENCODER_CNT_PER_OUT_REV \
    (CAR_ENCODER_CNT_PER_MOTOR_REV * CAR_GEAR_RATIO)        /* 1560 */

#define CAR_WHEEL_DIAMETER_MM      65.0f   /* 轮径：待实测确认 */
#define CAR_WHEEL_CIRCUMFERENCE_MM (3.14159265f * CAR_WHEEL_DIAMETER_MM)

/* 控制周期：编码器差分与速度换算都按这个周期定义 */
#define CAR_CONTROL_PERIOD_MS      10U

#define CAR_DEBUG_BAUDRATE         115200U

/* Keep disabled for normal startup. Enable only with the wheels lifted. */
#define CAR_STARTUP_MOTOR_TEST     0
#define CAR_STARTUP_TEST_COMMAND   0

#endif
